"""One owner-authorized closeout for an ended direct reviewer; no launch/rebind.

Reservations are separate from historical launch records. This is a read-only
review conduct contract, not OS sandbox enforcement or candidate admission.
"""
from copy import deepcopy
from hashlib import sha256
import json
from pathlib import Path

from cuhg.codex_hooks.child_lifecycle import LifecycleStore, _runtime_context, _fail
from cuhg.codex_hooks.launch_preflight import launch_issues
from cuhg.models.review_hierarchy import strictly_higher


def _digest(value):
    return sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def _candidate(record, request):
    root = Path(record['identity']['worktree_root'])
    files = request['candidate_files']
    if not isinstance(files, dict) or not files or _digest(files) != request['candidate_digest']:
        raise _fail('REVIEW_CANDIDATE_INVALID', 'Exact candidate file manifest is required.')
    for name, digest in files.items():
        path = root / name
        if Path(name).is_absolute() or not path.resolve().is_relative_to(root):
            raise _fail('REVIEW_CANDIDATE_INVALID', 'Candidate paths must stay inside the registered workspace.')
        if sha256(path.read_bytes()).hexdigest() != digest:
            raise _fail('REVIEW_CANDIDATE_CHANGED', 'Candidate bytes changed before review.')


def _ended(store, record):
    child = record['child']
    observed = child.get('runtime_observation', {})
    turn = observed.get('turn_id')
    if observed.get('state') != 'MATCH' or not turn or not record.get('last_exit_digest'):
        raise _fail('REVIEW_RUNTIME_UNVERIFIED', 'A matched ended reviewer is required.')
    raw = Path(child['transcript_ref']).read_bytes()
    rows = [json.loads(line) for line in raw.splitlines() if line.strip()]
    contexts = [row['payload'] for row in rows if row.get('type') == 'turn_context']
    events = [row['payload'] for row in rows if row.get('type') == 'event_msg'
              and row.get('payload', {}).get('type') in {'task_started', 'task_complete', 'turn_aborted'}]
    if (not contexts or contexts[-1].get('turn_id') != turn or not events
            or events[-1].get('type') != 'task_complete' or events[-1].get('turn_id') != turn):
        raise _fail('REVIEW_NOT_ENDED', 'Latest observed reviewer turn must be complete; running/unknown is refused.')
    runtime = _runtime_context(record, {'turn_id': turn})
    if runtime['state'] != 'MATCH':
        raise _fail('REVIEW_RUNTIME_UNVERIFIED', 'Raw runtime differs from the registered reviewer.')
    store._revalidate_frozen_validator(record)
    usages = [row['payload']['info']['total_token_usage'] for row in rows
              if row.get('type') == 'event_msg' and row.get('payload', {}).get('type') == 'token_count'
              and isinstance(row['payload'].get('info'), dict)
              and isinstance(row['payload']['info'].get('total_token_usage'), dict)]
    if not usages or type(usages[-1].get('total_tokens')) is not int or usages[-1]['total_tokens'] < 0:
        raise _fail('REVIEW_USAGE_UNKNOWN', 'Observed cumulative reviewer usage is required.')
    return {'transcript_sha256': sha256(raw).hexdigest(), 'turn_id': turn,
            'cumulative_usage': usages[-1], 'runtime_observation': runtime}


def _validate(store, record, request, cwd):
    for key in ('launch_id', 'session_id', 'run_id', 'task_id'):
        if request[key] != record[key]:
            raise _fail('REVIEW_IDENTITY_MISMATCH', 'Closeout must retain the original task and launch.')
    if (record.get('continuation_context') is not None or not record.get('claim')
            or request['child_id'] != record['child']['child_id']):
        raise _fail('REVIEW_IDENTITY_MISMATCH', 'Only the existing direct reviewer is eligible.')
    if launch_issues(record, cwd):
        raise _fail('REVIEW_IDENTITY_MISMATCH', 'Client and registered source must still match.')
    profile = record['profile']
    if profile.get('profile_id') not in {'cuhg_gpt6_astra_reviewer', 'cuhg_gpt6_sol_reviewer'}:
        raise _fail('REVIEW_PROFILE_REQUIRED', 'This route is for existing named reviewers only.')
    if request.get('scope') != 'READ_ONLY_REVIEW_CLOSEOUT' or request.get('max_consumptions') != 1:
        raise _fail('REVIEW_SCOPE_INVALID', 'Only one read-only closeout invocation is permitted.')
    approval = request['owner_approval']
    # Host supplies the explicit owner decision, never a child self-authorization.
    for key in ('launch_id', 'child_id', 'task_id', 'candidate_digest'):
        if approval.get(key) != request[key]:
            raise _fail('REVIEW_APPROVAL_MISMATCH', 'Owner approval must name this exact closeout.')
    if approval.get('authorized') is not True or not approval.get('source'):
        raise _fail('REVIEW_APPROVAL_REQUIRED', 'Explicit owner approval is required.')
    author = request['author']
    ordinary = strictly_higher(author['model'], author['effort'], profile['model'], profile['effort'], author_kind='HOST_CODEX')
    exception = (approval.get('exception') == 'SAME_TASK_ASTRA_HIGH_TO_ASTRA_XHIGH'
                 and (author['model'], author['effort'], profile['model'], profile['effort'])
                 == ('gpt-6-astra', 'high', 'gpt-6-astra', 'xhigh'))
    if not ordinary and not exception:
        raise _fail('REVIEW_HIERARCHY_UNSATISFIED', 'No applicable exact-candidate owner exception.')
    if not isinstance(request.get('prompt_sha256'), str) or len(request['prompt_sha256']) != 64:
        raise _fail('REVIEW_PROMPT_REQUIRED', 'Freeze the exact followup prompt.')
    _candidate(record, request)
    return _ended(store, record)


def reserve(root, *, request, client_cwd, owner_authorized=False, check=False):
    if not owner_authorized:
        raise _fail('REVIEW_APPROVAL_REQUIRED', 'Host owner authorization is required.')
    store = LifecycleStore(Path(root) / 'lifecycle')
    with store._locked(read_only=check) as state:
        record = state['launches'][request['launch_id']]
        observed = _validate(store, record, request, client_cwd)
        prior = state.get('direct_review_closeouts', {}).get(record['launch_id'])
        if prior:
            if prior['request'] != request:
                raise _fail('REVIEW_CLOSEOUT_ALREADY_RESERVED', 'Do not replace or reset this task closeout.')
            return deepcopy(prior)
        receipt = {'status': 'CHECK_ONLY' if check else 'RESERVED', 'request': deepcopy(request),
                   'baseline': observed, 'launch_sha256': _digest(record), 'consumption': None,
                   'dispatch_refunded': False, 'claim_admitted': False,
                   'os_read_only_enforced': False}
        if not check:
            state.setdefault('direct_review_closeouts', {})[record['launch_id']] = receipt
        return deepcopy(receipt)


def _receipt(state, launch_id, *, successor=False):
    """Select explicitly; never reopen or fall back from a consumed successor."""
    original = state.get('direct_review_closeouts', {}).get(launch_id)
    if not successor:
        return original
    receipt = state.get('direct_review_successors', {}).get(launch_id)
    if receipt and (not original or original.get('status') != 'REVIEW_RETURNED'
                    or _digest(original) != receipt['predecessor_sha256']):
        raise _fail('REVIEW_PREDECESSOR_CHANGED', 'Completed predecessor must remain unchanged.')
    return receipt


def reserve_successor(root, *, request, predecessor_sha256, client_cwd,
                      owner_authorized=False, check=False):
    """One separately approved additional review after a completed closeout.

    This is deliberately a single successor slot, not an arbitrary round registry.
    The original receipt and launch are retained; cumulative costs are not reset.
    """
    if not owner_authorized:
        raise _fail('REVIEW_APPROVAL_REQUIRED', 'Host owner authorization is required.')
    store = LifecycleStore(Path(root) / 'lifecycle')
    with store._locked(read_only=check) as state:
        launch_id = request['launch_id']
        original = _receipt(state, launch_id)
        if (not original or original.get('status') != 'REVIEW_RETURNED'
                or not original.get('consumption') or not original.get('return')
                or _digest(original) != predecessor_sha256):
            raise _fail('REVIEW_PREDECESSOR_INVALID', 'Exact completed receipt is required.')
        approval = request['owner_approval']
        if (approval.get('predecessor_sha256') != predecessor_sha256
                or type(approval.get('additional_reviews')) is not int
                or approval['additional_reviews'] != 1):
            raise _fail('REVIEW_APPROVAL_MISMATCH', 'Approval must bind this predecessor and one additional review.')
        prior = _receipt(state, launch_id, successor=True)
        if prior:
            if prior['request'] != request:
                raise _fail('REVIEW_SUCCESSOR_ALREADY_RESERVED', 'Never replace or reset the additional review.')
            # Inspection of an existing request grants no execution, even after
            # a crash or return. Consumption performs all live checks again.
            if client_cwd != state['launches'][launch_id]['identity']['worktree_root']:
                raise _fail('REVIEW_IDENTITY_MISMATCH', 'Client must retain the registered workspace.')
            return deepcopy(prior)
        record = state['launches'][launch_id]
        observed = _validate(store, record, request, client_cwd)
        if observed != original['return']['observed']:
            raise _fail('REVIEW_OBSERVATION_CHANGED', 'Successor must start at the actual recorded return, with all usage retained.')
        receipt = {'status': 'CHECK_ONLY' if check else 'RESERVED',
                   'request': deepcopy(request), 'baseline': observed,
                   'predecessor_sha256': predecessor_sha256,
                   'launch_sha256': _digest(record), 'consumption': None,
                   'dispatch_refunded': False, 'claim_admitted': False,
                   'os_read_only_enforced': False}
        if not check:
            state.setdefault('direct_review_successors', {})[launch_id] = receipt
        return deepcopy(receipt)


def consume(root, *, launch_id, session_id, child_id, client_cwd, tool_use_id, message):
    if not isinstance(tool_use_id, str) or not tool_use_id.strip():
        raise _fail('REVIEW_TOOL_ID_REQUIRED', 'One actual invocation identity is required.')
    store = LifecycleStore(Path(root) / 'lifecycle')
    with store._locked() as state:
        receipt = _receipt(state, launch_id,
                           successor=launch_id in state.get('direct_review_successors', {}))
        if not receipt or receipt['status'] != 'RESERVED' or receipt['consumption'] is not None:
            raise _fail('REVIEW_CLOSEOUT_NOT_RESERVED', 'Consumed/unknown outcomes cannot launch again.')
        if ('predecessor_sha256' in receipt and tool_use_id ==
                state['direct_review_closeouts'][launch_id]['consumption']['tool_use_id']):
            raise _fail('REVIEW_TOOL_ID_REUSED', 'The completed invocation identity cannot be reused.')
        request = receipt['request']; record = state['launches'][launch_id]
        if (session_id, child_id) != (request['session_id'], request['child_id']):
            raise _fail('REVIEW_IDENTITY_MISMATCH', 'Invocation differs from approved reviewer.')
        delivery = receipt.get('frozen_brief_delivery')
        if delivery is None:
            if not isinstance(message, str) or sha256(message.encode()).hexdigest() != request['prompt_sha256']:
                raise _fail('REVIEW_PROMPT_CHANGED', 'No independently bound frozen brief for this transport.')
        else:
            # Native clients may transport message opaquely. The message is not
            # the authority in this explicitly bound mode: reviewer identity,
            # the approved task/candidate and this frozen Host brief are.
            brief = Path(delivery['path'])
            if (str(brief.resolve()) != delivery['resolved_path']
                    or sha256(brief.read_bytes()).hexdigest() != request['prompt_sha256']):
                raise _fail('REVIEW_BRIEF_CHANGED', 'Approved frozen brief changed before consumption.')
        observed = _validate(store, record, request, client_cwd)
        expected = receipt.get('terminal_observation_reconciliation', {}).get('observed', receipt['baseline'])
        if _digest(record) != receipt['launch_sha256'] or observed != expected:
            raise _fail('REVIEW_OBSERVATION_CHANGED', 'Reconcile changed evidence without resetting the closeout.')
        receipt['status'] = 'CONSUMED_OUTCOME_UNKNOWN'
        receipt['consumption'] = {'tool_use_id': tool_use_id}
        return deepcopy(receipt)


def record_return(root, *, launch_id, client_cwd, successor=False):
    """Record a fresh terminal turn and usage delta, never its review verdict."""
    store = LifecycleStore(Path(root) / 'lifecycle')
    with store._locked() as state:
        receipt = _receipt(state, launch_id, successor=successor)
        if not receipt or receipt['status'] not in {'CONSUMED_OUTCOME_UNKNOWN', 'REVIEW_RETURNED'}:
            raise _fail('REVIEW_CLOSEOUT_NOT_CONSUMED', 'A consumed invocation is required.')
        record = state['launches'][launch_id]
        observed = _validate(store, record, receipt['request'], client_cwd)
        base = receipt['baseline']
        if observed['turn_id'] == base['turn_id']:
            raise _fail('REVIEW_RETURN_NOT_OBSERVED', 'Original terminal turn is not a new closeout return.')
        delta = observed['cumulative_usage']['total_tokens'] - base['cumulative_usage']['total_tokens']
        if delta < 0:
            raise _fail('REVIEW_USAGE_DECREASED', 'Cumulative accounting cannot reset.')
        result = {'observed': observed, 'additional_total_tokens': delta, 'claim_admitted': False}
        if receipt['status'] == 'REVIEW_RETURNED':
            if receipt['return'] != result:
                raise _fail('REVIEW_RETURN_CHANGED', 'Do not rewrite a recorded closeout.')
            return deepcopy(receipt)
        receipt['return'] = result
"""Temporary PreToolUse overlay: reserved direct reviews only, else installed hook.

The descriptor and all other hooks stay authoritative and unchanged. Installing
this overlay does not install the workspace-job candidate or change hook trust.
"""
from pathlib import Path
import json
import subprocess
import sys

if __package__ in (None, ''):
    sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from cuhg.codex_hooks.global_dispatch import state_root, FOLLOWUP_TOOLS, _decision, _tool_name
from cuhg.codex_hooks.child_lifecycle import LifecycleStore
from cuhg.codex_hooks.direct_review_closeout import consume
from cuhg.errors import CuhError


def handle(event, *, root):
    tool = _tool_name(event.get('tool_name', ''))
    if event.get('hook_event_name') != 'PreToolUse' or tool not in FOLLOWUP_TOOLS:
        return None
    input_ = event.get('tool_input', {})
    if not isinstance(input_, dict):
        return None
    session = event.get('session_id', '')
    target = input_.get('target', input_.get('id', input_.get('agent_id')))
    store = LifecycleStore(Path(root) / 'lifecycle')
    binding = store.get_child(session_id=session, child_id=str(target))
    if binding is None or binding.get('continuation_context') is not None:
        return None
    with store._locked(read_only=True) as state:
        if binding['launch_id'] not in state.get('direct_review_closeouts', {}):
            return None
    try:
        consume(root, launch_id=binding['launch_id'], session_id=session,
                child_id=binding['child']['child_id'], client_cwd=event.get('cwd'),
                tool_use_id=event.get('tool_use_id'), message=input_.get('message'))
        return _decision(True, 'RESERVED_DIRECT_REVIEW_CLOSEOUT')
    except (CuhError, ValueError, TypeError, KeyError, OSError):
        return _decision(False, 'DIRECT_REVIEW_CLOSEOUT_NOT_RESERVED: preserve the prior claim and observe the actual outcome.')


def main():
    if sys.argv[1:] == ['--self-check']:
        print('GLOBAL_ROUTING_HOOK_SELF_CHECK_PASS')
        return 0
    raw = sys.stdin.read()
    event = json.loads(raw)
    result = handle(event, root=state_root())
    if result is not None:
        print(json.dumps(result))
        return 0
    descriptor = json.loads((state_root().parents[2]/'runtime/global-execution-policy.json').read_text())
    authority = Path(descriptor['policy_authority']['repo_root'])
    installed = authority/'src/cuhg/codex_hooks/global_dispatch.py'
    if installed.resolve() == Path(__file__).resolve():
        raise ValueError('OVERLAY_MUST_FORWARD_TO_INSTALLED_AUTHORITY')
    forwarded = subprocess.run([sys.executable, '-B', str(installed)], input=raw, text=True)
    return forwarded.returncode


