    def register_launch(self, *, repo_root: str | Path, worktree_root: str | Path, run_id: str,
                        task_id: str, session_id: str, profile: Mapping[str, object],
                        validator_argv: Sequence[str] | None = None, task_name: str | None = None, continuation_context: dict | None = None,
                        _commit_guard: Callable[[], ContextManager] | None = None,
                        _routing_registration: dict | None = None) -> dict[str, object]:
        identity = _identity(Path(repo_root), Path(worktree_root))
        from cuhg.codex_hooks.harness_result import freeze_contract
        harness_contract = freeze_contract(Path(identity["worktree_root"]), run_id, task_id)
        frozen_profile = _profile(profile)
        resource_selection = None
        if continuation_context is not None:
            if not isinstance(continuation_context, dict):
                raise _fail('CONTINUATION_RESOURCE_BINDING_INVALID', 'Workspace run and selection are required.')
            run = _absolute(continuation_context.get('run_dir'), 'continuation.run_dir')
            from cuhg.models.native_workspace_job import _job
            from cuhg.models.mixed_worker_routing import _packet, _state
            job = _job(run)
            selected = next((row for row in _state(run, _packet(run))['dispatches']
                             if row['selection_id'] == continuation_context.get('selection_id')), None)
            if job['workspace'] != identity['worktree_root'] or job['task_id'] != task_id or selected is None or (
                    selected['model'], selected['model_reasoning_effort']) != (frozen_profile['model'], frozen_profile['effort']):
                raise _fail('CONTINUATION_RESOURCE_BINDING_INVALID', 'Resource policy must belong to this exact task, checkout and worker.')
            resource_selection = selected
            continuation_context = {'run_dir': str(run), 'selection_id': selected['selection_id']}

        frozen_argv: list[str] | None = None
        if validator_argv is not None:
            if not isinstance(validator_argv, (list, tuple)) or not validator_argv or any(not isinstance(v, str) or not v or "\x00" in v for v in validator_argv):
                raise _fail("VALIDATOR_ARGV_INVALID", "validator_argv must be a fixed nonempty argv array.")
            frozen_argv = list(validator_argv)
        validator_files = {}
        for argument in frozen_argv or []:
            candidate_path = Path(argument.split('::',1)[0])
            selected = candidate_path if candidate_path.is_absolute() else Path(identity['worktree_root']) / candidate_path
            if not argument.startswith('-') and candidate_path.suffix == '.py' and not selected.is_file():
                raise _fail('VALIDATOR_FILE_MISSING', 'A Python validator path must exist before dispatch.')
            if selected.is_file():
                selected = selected.resolve()
                validator_files[str(selected)] = sha256(selected.read_bytes()).hexdigest()
        record = {"schema": _SCHEMA, "run_id": _text(run_id, "run_id"), "task_id": _text(task_id, "task_id"),
                  "session_id": _text(session_id, "session_id"), "task_name": task_name,
                  "identity": identity, "profile": frozen_profile, "validator_argv": frozen_argv, "harness_contract": harness_contract, "validator_files": validator_files,
                  "claim": None, "child": None, "exits": {}, "continuation_context": continuation_context}
        launch_id = "cl_" + sha256(canonical_json_bytes({k: record[k] for k in ("run_id", "task_id", "session_id", "identity", "profile")})).hexdigest()[:32]
        record["launch_id"] = launch_id
        with self._locked(commit_guard=_commit_guard, registration=(None if _routing_registration is None else {**_routing_registration,'launch_id':launch_id})) as state:
            launches = self._launches(state)
            existing = launches.get(launch_id)
            if existing is not None:
                immutable = ("schema", "launch_id", "run_id", "task_id", "session_id", "task_name", "identity", "profile", "validator_argv", "harness_contract", "validator_files")
                if any(existing.get(key) != record.get(key) for key in immutable):
                    raise _fail("LAUNCH_ID_CONFLICT", "A launch id already has different immutable identity.")
                if existing.get('continuation_context') != continuation_context:
                    bound = existing.get('child')
                    # Connect an existing workspace expense to its same child;
                    # preserve launch identity, expenditure and resource limits.
                    attachable = existing.get('continuation_context') is None and continuation_context is not None and (
                        (bound is None and existing.get('claim') is None) or
                        (isinstance(bound, dict) and bound.get('runtime_observation', {}).get('state') == 'MATCH'
                         and resource_selection.get('observation', {}).get('thread_id') == bound.get('child_id')
                         and resource_selection.get('status') in {'CANDIDATE_RETURNED', 'WRITTEN_ARTIFACT_READY', 'REVIEW_READY'}))
                    if not attachable:
                        raise _fail('LAUNCH_ID_CONFLICT', 'Resource binding cannot be replaced or attached to an unverified child.')
                    existing['continuation_context'] = continuation_context
                return dict(existing)
            launches[launch_id] = record
        return dict(record)

    def repair_unclaimed_validator(self, launch_id: str, *, session_id: str,
    def _validate_event_identity(self, record: Mapping[str, object], event: Mapping[str, object], *, require_cwd: bool) -> None:
        if not isinstance(event, Mapping): raise _fail("CHILD_EVENT_INVALID", "Child event must be a mapping.")
        identity = record["identity"]
        if not isinstance(identity, Mapping): raise _fail("LIFECYCLE_STATE_INVALID", "Stored identity is invalid.")
        cwd = event.get("cwd")
        if require_cwd and not isinstance(cwd, str): raise _fail("CHILD_CWD_MISSING", "Child event must report actual cwd.")
        if cwd is not None and str(_absolute(cwd, "event.cwd")) != identity["worktree_root"]:
            raise _fail("CHILD_CWD_MISMATCH", "Child event cwd differs from bound worktree.")
        for key in ("repo_root", "repo_id", "worktree_id", "worktree_root", "head_commit", "run_id", "task_id", "session_id"):
            expected = identity.get(key) if key in identity else record.get(key)
            provided = event.get(key)
            if provided is not None and provided != expected:
                raise _fail("CHILD_IDENTITY_MISMATCH", f"Child event {key} differs from registered identity.")
        actual = _identity(Path(identity["repo_root"]), Path(identity["worktree_root"]))
        if actual != dict(identity): raise _fail("CHILD_IDENTITY_CHANGED", "Bound Git/worktree identity changed before child exit.")

    def _revalidate_harness_contract(self, record: Mapping[str, object]) -> None:
        """Check the source-only local harness bundle without importing it."""
        identity = record["identity"]
        assert isinstance(identity, Mapping)
        contract = record.get('harness_contract')
        if contract is not None and (not isinstance(contract, Mapping) or 'validator_bundle' not in contract):
            raise _fail('HARNESS_RE_REGISTRATION_REQUIRED',
                        'Legacy harness contract has no validator bundle identity.')
        from cuhg.codex_hooks.harness_result import freeze_contract
        try:
            current_contract = freeze_contract(Path(identity["worktree_root"]), record["run_id"], record["task_id"],
                                               validate_protocol=False)
        except Exception as error:
            raise _fail("HARNESS_CONTRACT_CHANGED", "Frozen harness validator is no longer available.") from error
        if current_contract != record.get("harness_contract"):
            raise _fail("HARNESS_CONTRACT_CHANGED", "Frozen harness validator changed after child exit.")

    def _revalidate_frozen_validator(self, record: Mapping[str, object]) -> None:
        """Reject a cached success when its registered validator changed."""
        self._revalidate_harness_contract(record)
        for filename, expected in record.get("validator_files", {}).items():
            path = Path(filename)
            if not path.is_file() or sha256(path.read_bytes()).hexdigest() != expected:
                raise _fail("VALIDATOR_CHANGED", "Frozen validator dependency changed after child exit.", path=filename)

    def _revalidate_cached_exit(self, record: Mapping[str, object], event: Mapping[str, object]) -> dict[str, object]:
        """Check live bindings before using an idempotent exit receipt."""
        self._validate_event_identity(record, event, require_cwd=True)
        runtime = _runtime_context(record, event)
        if runtime["state"] != "MATCH":
            raise _fail("CHILD_RUNTIME_CHANGED", "Bound child runtime transcript changed after child exit.",
                        state=runtime["state"], reason=runtime.get("reason"))
        self._revalidate_frozen_validator(record)
        if (record.get('harness_contract') or {}).get('result_protocol')=='cuhg-result-artifact/v2':
            from cuhg.codex_hooks.harness_result import checked_result_artifact
            try:checked_result_artifact(Path(record['identity']['worktree_root']),record,dict(event))
            except ValueError as error:raise _fail('CHILD_RESULT_ARTIFACT_CHANGED',str(error)) from error
        return runtime

    def child_exit(self, *, session_id: str, child_id: str, event: Mapping[str, object]) -> dict[str, object]:
        session, child = _text(session_id, "session_id"), _text(child_id, "child_id")
        digest = sha256_digest(canonical_json_bytes(event))
        initial = self.get_child(session, child)
        if initial is None or initial['child']['child_id'] != child:
            raise _fail("CHILD_BINDING_MISSING", "No exact bound launch exists for child exit.")
        # A validator may run for two 60-second stages. Other launches, sessions
        # and read-only observers must not wait on that external computation.
        with (self.root / (initial['launch_id'] + '.validation.lock')).open('a+') as lock:
            try:
                fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                return {'status': 'VALIDATION_IN_PROGRESS', 'decision': 'NON_ADMISSION',
                        'launch_id': initial['launch_id'], 'claim_admitted': False}
            with self._locked(read_only=True) as state:
                record = deepcopy(self._launches(state)[initial['launch_id']])
            version = canonical_json_bytes(record)
            prior_success = any(exit.get('status') == 'VALIDATOR_PASSED'
                                for exit in record['exits'].values())
            if prior_success:
                runtime = self._revalidate_cached_exit(record, event)
                if digest in record['exits']:
                    return deepcopy(record['exits'][digest])
            else:
                self._validate_event_identity(record, event, require_cwd=True)
                runtime = _runtime_context(record, event)
                if digest in record['exits']:
                    return deepcopy(record['exits'][digest])
            if runtime['state'] == 'MATCH':
                # This is a source-only bundle check immediately before the
                # actual external validator.  It does not import or execute it.
                self._revalidate_harness_contract(record)
                receipt = self._run_validator(record, event, digest)
                self._validate_event_identity(record, event, require_cwd=True)
                try:
                    # Do not accept a pass if the validator or one of its local
                    # helpers drifted while the external process was running.
                    self._revalidate_frozen_validator(record)
                except CuhError as error:
                    receipt.update(status=error.code, decision='BLOCKED_BY_VALIDATOR')
            else:
                receipt = {'schema': _SCHEMA, 'launch_id': record['launch_id'], 'child_id': child,
                           'event_digest': digest, 'status': 'RUNTIME_' + runtime['state'],
                           'decision': 'BLOCKED_BY_RUNTIME', 'claim_admitted': False}
            receipt['runtime_observation'] = runtime
            with self._locked() as state:
                mutable = self._launches(state)[record['launch_id']]
                if canonical_json_bytes(mutable) != version:
                    receipt.update(status='LIFECYCLE_CHANGED', decision='NON_ADMISSION')
                else:
                    mutable['child']['runtime_observation'] = runtime
                    if runtime['state'] == 'MATCH':
                        mutable['child']['runtime_profile'] = _observed_profile(runtime['observed'])
                mutable['exits'][digest] = receipt
                mutable['last_exit_digest'] = digest
            return deepcopy(receipt)

    def _run_validator(self, record: Mapping[str, object], event: Mapping[str, object], digest: str) -> dict[str, object]:
        child = record["child"]
        identity = record["identity"]
        assert isinstance(child, Mapping) and isinstance(identity, Mapping)
        receipt: dict[str, object] = {"schema": _SCHEMA, "launch_id": record["launch_id"], "child_id": child["child_id"],
            "event_digest": digest, "identity": dict(identity), "profile": dict(record["profile"]),
            "transcript_ref": event.get("agent_transcript_path"), "claim_admitted": False}
        argv = record.get("validator_argv")
        for filename, expected in record.get('validator_files', {}).items():
            path = Path(filename)
            if not path.is_file() or sha256(path.read_bytes()).hexdigest() != expected:
                receipt.update(status="VALIDATOR_CHANGED", decision="BLOCKED_BY_VALIDATOR")
                return receipt
        if argv is None and not record.get("harness_contract"):
            receipt.update({"status": "RUNTIME_ONLY_SUCCESS", "decision": "NON_ADMISSION", "validator": "NOT_DECLARED"})
            return receipt
        payload = canonical_json_bytes(dict(record)).decode("utf-8")
        event_path = self.root / ("event-" + digest.removeprefix("sha256:") + ".json")
        event_path.write_bytes(canonical_json_bytes(event))
        event_path.chmod(0o600)
        spool = self.root / "validator-spools"; spool.mkdir(exist_ok=True)
        env = {"PATH": "/usr/bin:/bin", "PYTHONNOUSERSITE": "1", "PYTHONDONTWRITEBYTECODE": "1",
               "CUHG_CHILD_RECEIPT": payload, "CUHG_CHILD_EVENT_PATH": str(event_path)}
        if record.get("harness_contract"):
            import sys
            gate_argv = ("/usr/bin/env", sys.executable, str(Path(__file__).with_name('harness_result.py')))
            gate = ProcessSpec.create(lease_id="harness-result-gate", argv=gate_argv,
                cwd=str(identity["worktree_root"]), cwd_roots=(str(identity["worktree_root"]),),
                spool_root=str(spool), spool_roots=(str(spool),), environment=env,
                allowed_environment_names=tuple(env), runner_id="harness-result-gate", runner_version="1",timeout_ms=60_000)
            check = ProcessRunner().run(gate)
            try:
                check.verify_spools(); receipt["harness_validation"] = check.to_record()
                if check.exit_code in (0,3) and isinstance(event.get('result_artifact'),dict):
                    receipt['result_artifact']=deepcopy(event['result_artifact'])
                if check.exit_code == 3:
                    receipt.update(status="RESULT_NONPASS", schema_validation="VALID", task_status="NONPASS", decision="NON_ADMISSION")
                    return receipt
                if check.exit_code == 4:
                    receipt.update(status="VALIDATION_UNAVAILABLE", decision="BLOCKED_BY_VALIDATOR")
                    return receipt
                if check.exit_code != 0:
                    receipt.update(status="VALIDATOR_FAILED", decision="BLOCKED_BY_VALIDATOR")
                    return receipt
            finally: check.close_spools()
            if argv is None:
                receipt.update(status="VALIDATOR_PASSED", decision="LOCAL_CANDIDATE_VALIDATED")
                return receipt
        spec = ProcessSpec.create(lease_id="child-validator-" + str(record["launch_id"]), argv=("/usr/bin/env", *argv),
            cwd=str(identity["worktree_root"]), cwd_roots=(str(identity["worktree_root"]),), spool_root=str(spool), spool_roots=(str(spool),),
            environment=env, allowed_environment_names=tuple(env), runner_id="cuhg-child-lifecycle", runner_version="1", timeout_ms=60_000)
        execution = ProcessRunner().run(spec, run_id="validator-" + digest.removeprefix("sha256:")[:32])
        try:
            execution.verify_spools()
            receipt["validator_execution"] = execution.to_record()
            if execution.exit_code == 0:
                receipt.update({"status": "VALIDATOR_PASSED", "decision": "LOCAL_CANDIDATE_VALIDATED"})
            else:
                receipt.update({"status": "VALIDATOR_FAILED", "decision": "BLOCKED_BY_VALIDATOR"})
        finally:
            execution.close_spools()
        return receipt

    def observe_wait(self, session_id: str, targets: Sequence[str], progress_token: str | None = None, *, progress_tokens: Mapping[str, str | None] | None = None) -> dict[str, object]:
