"""Versioned owner policy for continuous operation; historical jobs stay frozen."""
from __future__ import annotations
import json
import os
from pathlib import Path

DEFAULT_PATH = Path.home() / '.config/cuh-g/continuous-operation.json'


def load_policy(path: Path | None = None) -> dict:
    path = path or Path(os.environ.get('CUHG_CONTINUOUS_POLICY', str(DEFAULT_PATH)))
    if not path.exists():
        return {}
    value = json.loads(path.read_text())
    if not isinstance(value, dict) or value.get('schema') != 'cuhg-continuous-operation/v1':
        raise ValueError('CONTINUOUS_POLICY_INVALID')
    return value


def validate_budget(value: dict) -> dict:
    if not isinstance(value, dict) or set(value) != {'mode', 'soft_target', 'explicit_hard_limit'}:
        raise ValueError('ADAPTIVE_BUDGET_INVALID')
    if value['mode'] != 'adaptive' or type(value['soft_target']) is not int or value['soft_target'] <= 0:
        raise ValueError('ADAPTIVE_BUDGET_INVALID')
    hard = value['explicit_hard_limit']
    if hard is not None and (type(hard) is not int or hard <= 0):
        raise ValueError('ADAPTIVE_BUDGET_INVALID')
    return dict(value)


def assess_budget(policy: dict, observed_tokens: int | None) -> dict:
    policy = validate_budget(policy)
    if observed_tokens is not None and (type(observed_tokens) is not int or observed_tokens < 0):
        raise ValueError('BUDGET_OBSERVATION_INVALID')
    hard = policy['explicit_hard_limit']
    if hard is not None and (observed_tokens is None or observed_tokens >= hard):
        return {'action': 'CHECKPOINT', 'reason': 'EXPLICIT_HARD_LIMIT_UNAVAILABLE_OR_EXHAUSTED'}
    if observed_tokens is None:
        return {'action': 'CONTINUE', 'reason': 'USAGE_UNKNOWN_NO_HARD_LIMIT'}
    if observed_tokens >= policy['soft_target']:
        return {'action': 'REPLAN_AND_CONTINUE', 'reason': 'SOFT_TARGET_EXCEEDED'}
    return {'action': 'CONTINUE', 'reason': 'WITHIN_SOFT_TARGET'}


def migrate_workspace_budget(run_dir: Path, revision: dict) -> dict:
    """Explicit, replay-safe migration of one open task, without resetting costs."""
    from hashlib import sha256
    from cuhg.models.native_workspace_job import _job, _save_job
    from cuhg.models.mixed_worker_routing import _locked
    required={'schema','task_id','owner_authorized','authorization_ref','authorization_sha256','budget','expected_job_digest'}
    if not isinstance(revision,dict) or set(revision)!=required or revision['schema']!='cuhg-adaptive-budget-migration/v1' or revision['owner_authorized'] is not True:
        raise ValueError('BUDGET_MIGRATION_INVALID')
    budget=validate_budget(revision['budget'])
    if sha256(Path(revision['authorization_ref']).read_bytes()).hexdigest()!=revision['authorization_sha256']:
        raise ValueError('BUDGET_MIGRATION_AUTHORIZATION_CHANGED')
    run=Path(run_dir).resolve()
    with _locked(run):
        job=_job(run)
        prior=job.get('adaptive_budget_migration')
        if prior is not None:
            if prior!=revision: raise ValueError('BUDGET_MIGRATION_ALREADY_APPLIED')
            return {'status':'ALREADY_APPLIED','task_id':job['task_id'],'job_digest':job['job_digest']}
        if job['task_id']!=revision['task_id'] or job['job_digest']!=revision['expected_job_digest']:
            raise ValueError('BUDGET_MIGRATION_IDENTITY_CHANGED')
        if job.get('status') not in {'PREPARED','IMPLEMENTED_CANDIDATE','WRITTEN_ARTIFACT','GUIDANCE_PACKET','REVIEW_REPORT','REVIEW_READY'}:
            raise ValueError('BUDGET_MIGRATION_NOT_OPEN')
        if any(job.get(k) for k in ('continuation_reservation','review_continuation_reservation','pre_candidate_continuation_reservation')):
            raise ValueError('BUDGET_MIGRATION_PENDING_WRITER')
        ledger=run/'mixed_workers.json'
        if ledger.exists():
            from cuhg.models.mixed_worker_routing import PENDING
            if any(item.get('status') in PENDING for item in json.loads(ledger.read_text()).get('dispatches',[])):
                raise ValueError('BUDGET_MIGRATION_PENDING_WRITER')
        # An explicit owner cap is separate authority; never erase it implicitly.
        previous=job.get('adaptive_budget',{}).get('explicit_hard_limit')
        if previous is not None and (budget['explicit_hard_limit'] is None or budget['explicit_hard_limit']>previous):
            raise ValueError('BUDGET_MIGRATION_EXPLICIT_CAP_PRESERVED')
        if job.get('token_budget_amendments') and budget['explicit_hard_limit'] != job['token_budget_amendments'][-1]['new_total_limit']:
            raise ValueError('BUDGET_MIGRATION_EXPLICIT_CAP_PRESERVED')
        job['adaptive_budget']=budget; job['adaptive_budget_migration']=dict(revision)
        updated=_save_job(run,job)
        return {'status':'APPLIED','task_id':job['task_id'],'job_digest':updated['job_digest'],
                'usage_events_preserved':len(job.get('usage_events',[])), 'budget':budget}


