"""Version-bound Host observations, not inferred capabilities or UI activation.

The observed field projection is supplied by the local client operator and bound
with its original bytes. This module does not reinterpret app-server schema as
hook schema and does not pretend a fixture is an actual client.
"""
from __future__ import annotations
import hashlib
import json
from pathlib import Path
from cuhg.canonical import canonical_json_bytes, sha256_digest


def _file(path: Path) -> dict:
    original=Path(path).absolute();resolved=original.resolve(strict=True)
    if not resolved.is_file():raise ValueError('CLIENT_SOURCE_REQUIRED')
    h=hashlib.sha256()
    with resolved.open('rb') as f:
        for block in iter(lambda:f.read(1024*1024),b''):h.update(block)
    return {'path':str(original),'resolved_path':str(resolved),'sha256':h.hexdigest()}


def bind_client_contract(*, binary: Path, version: str, schema_path: Path,
                         source_ref: str, session_id: str, source_kind: str) -> dict:
    if not all(isinstance(v,str) and v for v in (version,source_ref,session_id)):
        raise ValueError('CLIENT_IDENTITY_REQUIRED')
    if source_kind not in {'ACTUAL_CLIENT','APP_SERVER_PROBE','FIXTURE'}:raise ValueError('CLIENT_SOURCE_KIND_INVALID')
    binary_ref=_file(binary);schema_ref=_file(schema_path)
    if Path(schema_path).stat().st_size>1024*1024:raise ValueError('CLIENT_SCHEMA_LIMIT')
    schema=json.loads(Path(schema_path).read_bytes())
    if schema.get('schema')!='cuhg-observed-hook-fields/v1' or not isinstance(schema.get('events'),dict):
        raise ValueError('UNSUPPORTED_CLIENT_FIELD_PROJECTION')
    for name,row in schema['events'].items():
        if not isinstance(name,str) or not isinstance(row,dict) or not isinstance(row.get('handler_fields'),list) or any(not isinstance(k,str) for k in row['handler_fields']) or type(row.get('can_block')) is not bool:
            raise ValueError('CLIENT_EVENT_SCHEMA_INVALID')
    result={'schema':'cuhg-client-contract/v1','binary':binary_ref,'version':version,
            'field_projection':schema_ref,'events':schema['events'],'session_id':session_id,
            'source_ref':source_ref,'source_kind':source_kind,
            'active_client_verified':False,'evidence_scope':'HOST_RECORDED_VERSION_BOUND_FIELD_PROJECTION'}
    result['binding_digest']=sha256_digest(canonical_json_bytes(result))
    return result


def verify_client_contract(contract: dict) -> None:
    if contract.get('schema')!='cuhg-client-contract/v1':raise ValueError('CLIENT_CONTRACT_INVALID')
    body={k:v for k,v in contract.items() if k!='binding_digest'}
    if sha256_digest(canonical_json_bytes(body))!=contract.get('binding_digest'):raise ValueError('CLIENT_CONTRACT_CHANGED')
    for name in ('binary','field_projection'):
        if _file(Path(contract[name]['path']))!=contract[name]:raise ValueError('CLIENT_SOURCE_CHANGED')
    # The event projection must be the contents of the bound original, not a free override.
    schema=json.loads(Path(contract['field_projection']['path']).read_bytes())
    if schema.get('events')!=contract['events']:raise ValueError('CLIENT_PROJECTION_CHANGED')


def adapt_handler(handler: dict, event: str, contract: dict) -> dict:
    verify_client_contract(contract)
    row=contract['events'].get(event)
    if row is None:raise ValueError('CLIENT_EVENT_UNSUPPORTED:'+event)
    fields=set(row['handler_fields'])
    if not {'type','command','timeout'}<=fields:raise ValueError('CLIENT_REQUIRED_HANDLER_FIELDS_MISSING')
    if event=='PreToolUse' and row['can_block'] is not True:raise ValueError('CLIENT_PREDISPATCH_BLOCK_UNVERIFIED')
    return {k:v for k,v in handler.items() if k in fields}


def event_can_block(event: str, contract: dict) -> bool:
    verify_client_contract(contract)
    # A post-start callback cannot undo a child that has already started.
    return event!='SubagentStart' and contract['events'].get(event,{}).get('can_block') is True


def runtime_projection(requested: dict, observed: dict, *, contract: dict) -> dict:
    verify_client_contract(contract)
    keys=('model','effort','cwd','sandbox')
    missing=[key for key in keys if observed.get(key) is None or requested.get(key) is None]
    mismatch=[key for key in keys if key not in missing and observed[key]!=requested[key]]
    return {'state':'UNVERIFIED' if missing else 'MISMATCH' if mismatch else 'MATCH',
            'missing':missing,'mismatch':mismatch,'requested':requested,'observed':observed,
            'client_binding_digest':contract['binding_digest'],'source_kind':contract['source_kind'],
            'enforced_read_only':not missing and not mismatch and observed.get('sandbox')=='read-only' and contract['source_kind']=='ACTUAL_CLIENT'}
